				pcall(f)
				local f = X._snap_outline ~= nil and X._guide_v ~= nil and X._guide_h ~= nil
				local y2, q2, k2, P2, h2, _2, V2, J2, t2, b2, R2 = f and c.aero_snap == true, p2.X.Offset, p2.Y.Offset, C2.AbsoluteSize.X, C2.AbsoluteSize.Y, C2.AnchorPoint.X, C2.AnchorPoint.Y, C2.Size.X.Offset, C2.Size.Y.Offset, false, false

				if y2 then
					local L2, K2 = X._snap_outline, P2 * _2
					local O2, F2 = q2 - K2, h2 * V2
					L2.Position = b(0, O2, 0, k2 - F2)
