				function X.active_drag(L2)
					local K2, O2 = E.ViewportSize.X, E.ViewportSize.Y
					local F2, r2 = a(p2.X.Offset + (L2.Position.X - T2.X), 0, K2 - J2), a(p2.Y.Offset + (L2.Position.Y - T2.Y), 0, O2 - t2)
