					if f then
						p2, T2 = F2 - P2 * _2, r2 - h2 * V2
						L2 = w(p2 + P2 * 0.5 - K2 * 0.5) <= 10

						if L2 then
							F2 = K2 * 0.5 - P2 * 0.5 + P2 * _2
							p2 = F2 - P2 * _2
						end

						local P2 = w(T2 + h2 * 0.5 - O2 * 0.5) <= 10

						if P2 then
