	X.ui_sound_dir = X.directory .. "/sounds"
	X.ui_sound_ext = { mp3 = true, ogg = true, wav = true }
	X.ui_sound_presets = { Neverlose = "rbxassetid://8726881116" }
	X._sound_ids = {}
	X._sound_scan = { t = 0, names = nil, map = nil }

	X.sound_presets = function(f, f)
		local C2, y2 = X._sound_scan, os.clock()
		if not f and C2.names and y2 - C2.t < 5 then
			return C2.names, C2.map
		end
		C2.t = y2
		local f, y2 = {}, {}

		for q2, p2 in next, X.ui_sound_presets, nil do
			f[#f + 1] = q2
			y2[q2] = p2
		end

		pcall(function()
			local q2 = X.ui_sound_dir
			if not (listfiles and getcustomasset and isfolder and (isfolder(q2))) then
				return
			end
			local p2, T2, k2 = next, listfiles(q2)

			for P2, h2 in p2, T2, k2 do
				P2, q2 = (tostring(h2):match("[^/\\]+$") or ""):match("^(.*)%.([^%.]+)$")

				if P2 and q2 and P2 ~= "" and y2[P2] == nil and X.ui_sound_ext[string.lower(q2)] then
					local q2 = X._sound_ids[h2]

					if q2 == nil then
						local p2, T2 = pcall(getcustomasset, h2)
						q2 = p2 and type(T2) == "string" and T2 ~= "" and T2 or false
						X._sound_ids[h2] = q2
					end

					if q2 then
						f[#f + 1] = P2
						y2[P2] = q2
					end
				end
			end
		end)

		table.sort(f, function(q2, p2)
			return string.lower(q2) < string.lower(p2)
		end)

		C2.names = f
		C2.map = y2
		return f, y2
	end

	X.sound_items = function(f)
		local f, C2 = X:sound_presets(), { "Off" }

		for y2 = 1, #f, 1 do
