		end

		C2[#C2 + 1] = "Custom"
		return C2
	end

	X._last_ui_sound = {}
	X._ui_sounds = {}

	X.ui_sound = function(f, C2)
		f = c["ui_" .. C2 .. "_style"]
		if not f or f == "Off" then
			return
		end
		local y2

		if f == "Custom" then
			y2 = tostring(c["ui_" .. C2 .. "_custom"] or ""):gsub("%s", "")
			if y2 == "" then
				return
			end

			if not y2:find("rbxassetid://", 1, true) then
				y2 = "rbxassetid://" .. y2
			end
		else
			local q2, q2 = X:sound_presets()
			y2 = q2[f]
		end

		if not y2 then
			return
		end
		f = os.clock()
		if f - (X._last_ui_sound[C2] or 0) < 0.05 then
			return
		end
		X._last_ui_sound[C2] = f

		pcall(function()
			local f = X._ui_sounds[C2]

			if not (f and f.Parent) then
				f = Instance.new("Sound")
				f.Parent = V
				X._ui_sounds[C2] = f
			end

			if f.SoundId ~= y2 then
				f.SoundId = y2
			end

			f.Volume = c["ui_" .. C2 .. "_vol"] or 1
			f.TimePosition = 0
			f:Play()
		end)
	end

	X.config_dir = function(V)
		return X.directory .. "/configs/" .. tostring(X.game or "delta")
	end

	X.config_path = function(V, V)
		return X:config_dir() .. "/" .. tostring(V) .. ".cfg"
	end

	X.autoload_path = function(V)
		return X:config_dir() .. "/autoload.txt"
	end

	X.sanitize_config_name = function(V, V)
		V = tostring(V or ""):gsub("[%c<>:\"/\\|%?%*]", ""):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
		return if #V > 48 then (V:sub(1, 48):gsub("%s+$", "")) else V
	end

	X.config_names = function(V)
		local V, f, C2 = {}, pcall(listfiles, X:config_dir())
		if not (f and type(C2) == "table") then
			return V
		end

		for f, y2 in next, C2, nil do
			f = tostring(y2):match("[^/\\]+$") or (tostring(y2))

			if string.lower(f:sub(-4)) == ".cfg" then
				V[#V + 1] = f:sub(1, -5)
			end
		end

		table.sort(V, function(f, C2)
			return string.lower(f) < string.lower(C2)
		end)

		return V
	end

	X.config_meta = function(V, f, C2)
		if type(C2) ~= "string" then
			local y2, q2 = pcall(readfile, X:config_path(f))
			if not (y2 and type(q2) == "string") then
				return nil
			end
			C2 = q2
		end

		V = C2:match("\"__meta\"%s*:%s*(%b{})")
		if not V then
			return nil
		end
		local f, C2, y2, q2 = tonumber(V:match("\"created\"%s*:%s*([^,%}%s]+)")), tonumber(V:match("\"updated\"%s*:%s*([^,%}%s]+)")), V:match("\"version\"%s*:%s*\"([^\"]*)\""), V:match("\"game\"%s*:%s*\"([^\"]*)\"")
		if not (f or C2 or y2 or q2) then
			return nil
		end
		return { created = f, updated = C2, version = y2, game = q2 }
	end

	X.config_date = function(V, V)
		if type(V) ~= "number" then
			return "-"
		end
		local f, C2 = pcall(os.date, "%m/%d/%y", V)
		return f and C2 or "-"
	end

	X.flag_shape = function(V, f)
		V = type(f)
		if V ~= "table" then
			return V
		end

		if f.Color ~= nil and f.Transparency ~= nil then
			return "color"
		end

		if f.key ~= nil or f.mode ~= nil then
			return "keybind"
		end
		return "list"
	end

	X.seed_default = function(V, f, C2)
		V = c[f]
		if V == nil then
			return C2
		end

		if C2 ~= nil and X:flag_shape(V) ~= X:flag_shape(C2) then
			return C2
		end
		return V
	end

	X.config_compat = function(V, f, C2, y2)
		if type(y2) ~= "string" then
			local q2, p2 = pcall(readfile, X:config_path(f))
			if not (q2 and type(p2) == "string") then
				return nil
			end
			y2 = p2
		end

		local q2, p2 = pcall(function()
			return p:JSONDecode(y2)
		end)

		V = {
			mismatch = 0,
			total = 0,
			names = {},
		}

		if not (q2 and type(p2) == "table") then
			V.broken = true
			V.outdated = true
			return V
		end

		q2 = X.skip_flags or {}

		for T2, k2 in next, p2, nil do
			if type(T2) == "string" and T2:sub(1, 2) ~= "__" and not q2[T2] then
				V.total = V.total + 1
				local q2, p2 = c[T2]

				if q2 ~= nil and X:flag_shape(k2) ~= X:flag_shape(q2) then
					V.mismatch = V.mismatch + 1
					p2 = true
				end

				if p2 and #V.names < 8 then
					S(V.names, T2)
				end
			end
		end

		C2 = C2 or (X:config_meta(f, y2))
		V.version = C2 and C2.version
		C2 = X.config_version and (tostring(X.config_version))
		V.stale_version = C2 ~= nil and (V.version == nil or V.version ~= C2)
		V.outdated = V.mismatch > 0
		return V
	end

	X.config_warning = function(V, f)
		if not (f and f.outdated) then
			return nil
		end

		if f.broken then
			return "UNREADABLE - not valid config JSON. Loading will do nothing."
		end
		V = "OUTDATED - " .. f.mismatch .. " changed setting(s)"

		if #f.names > 0 then
			V ..= ": " .. n(f.names, ", ")
			V = if f.mismatch > #f.names then V .. ", ..." else V
		end

		return (if f.stale_version and f.version then V .. "   (saved on " .. f.version .. ", now " .. tostring(X.config_version or "?") .. ")" else V) .. ". It still loads; skipped settings keep their current value. Re-save to clean it up."
	end

	X.save_config = function(V, f)
		f = X:sanitize_config_name(f)
		if f == "" then
			return false
		end
		local C2, y2 = X:config_meta(f), os.time()

		V = pcall(function()
			writefile(X:config_path(f), X:get_config({
				created = C2 and C2.created or y2,
				updated = y2,
				version = tostring(X.config_version or "?"),
				game = tostring(X.game or "delta"),
			}))
		end)

		if V then
			X:config_list_update()
		end

		return V
	end

	X.delete_config = function(V, f)
		f = tostring(f or "")
		if f == "" then
			return false
		end
		V = pcall(delfile, X:config_path(f))

		if V then
			if X.loaded_config == f then
				X.loaded_config = nil
			end

			if X:autoload_name() == f then
				pcall(function()
					delfile(X:autoload_path())
				end)
			end

			X:config_list_update()
		end

		return V
	end

	X.load_config_file = function(V, f)
		f = tostring(f or "")
		local C2, y2 = pcall(readfile, X:config_path(f))
		if not (C2 and type(y2) == "string") then
			return false
		end
		C2 = X:config_meta(f, y2)
		if C2 and C2.game and C2.game ~= tostring(X.game or "delta") then
			return false
		end

		C2 = pcall(function()
			X:load_config(y2)
		end)

		if C2 then
			X.loaded_config = f
			V = X.config_repaint or X.config_refresh

			if V then
				pcall(V)
			end
		end

		return C2
	end

	X.set_autoload = function(V, V)
		local f = X:autoload_path()

		if V == nil or V == "" or X:autoload_name() == V then
			pcall(function()
				if isfile(f) then
					delfile(f)
				end
			end)

			if X.config_refresh then
				pcall(X.config_refresh)
			end

			return nil
		end

		pcall(writefile, f, V)

		if X.config_refresh then
			pcall(X.config_refresh)
		end

		return V
	end

	X.config_list_update = function(V)
		if X.config_refresh then
			pcall(X.config_refresh)
		end

		if not e then
			return
		end
		e.refresh_options(X:config_names())
	end

	X.get_config = function(V, e)
		if type(X.capture_ui_positions) == "function" then
			pcall(function()
				X:capture_ui_positions()
			end)
		end

		local f, C2 = {}, X.skip_flags or {}

		for y2, q2 in c, nil, nil do
			if not (C2[y2]) then
				if type(q2) == "table" and q2.key then
					V = {
						active = q2.active,
						mode = q2.mode,
						key = tostring(q2.key),
					}

					if type(q2.binds) == "table" then
						V.binds = {}

						for C2 = 1, #q2.binds, 1 do
							local p2 = q2.binds[C2]

							V.binds[C2] = {
								key = tostring(p2.key),
								mode = p2.mode,
								value = p2.value,
								active = p2.active,
								sets = p2.sets,
							}
						end
					end

					f[y2] = V
				elseif type(q2) == "table" and q2.Transparency and q2.Color then
