		k.change_health = function()
			if c.healthbar_holder and c.healthbar_holder.Parent ~= q.holder then
				return
			end

			if not (F and (F:FindFirstChild("Humanoid"))) then
				return
			end
			local K = F.Humanoid
			local j, H, e, f = K.MaxHealth * math.abs(math.sin(tick() * 2)) / K.MaxHealth, c[h("Health_Low")], c[h("Health_High")], g(255, 255, 255)
			f = if H and H.Color and e and e.Color then (H.Color:Lerp(e.Color, j)) else f

			if k._bar_horiz and k._bar_horiz.healthbar then
				q.healthbar.Size = UDim2.new(j, -2, 1, -2)
				q.healthbar.Position = UDim2.new(0, 1, 0, 1)
			else
				q.healthbar.Size = UDim2.new(1, -2, j, -2)
				q.healthbar.Position = UDim2.new(0, 1, 1 - j, 1)
			end

			q.healthbar.BackgroundColor3 = f
			q.hp_number.Text = tostring(math.floor(j * K.MaxHealth + 0.5))
		end

		k.refresh_elements = function()
			q.holder.Parent = V() and z.viewportframe or X.cache

			local V = {
