			for K, j in V, nil, nil do
				local H = c[h(K)]

				if H ~= nil then
					if type(j) == "table" then
						if H.Color then
							j[1].TextColor3 = H.Color
						end
					elseif not (k._chip_set and k._chip_set[j]) then
						j.Parent = H and q.holder or X.cache
