				end
			end

			V = c[h("Box_Type")]
			local K = V == nil or V == "Corner"

			if if k._show then k._show.box == true else c[h("Boxes")] == true then
				q.corners.ZIndex = 2
				q.box_handler.ZIndex = 2

				if K then
					q.corners.Parent = q.holder
					q.box_handler.Parent = X.cache
					q.box_outline.Parent = X.cache
				else
					q.box_handler.Parent = q.holder
					q.box_outline.Parent = q.holder
					q.corners.Parent = X.cache
				end
			else
				q.corners.Parent = X.cache
				q.box_handler.Parent = X.cache
				q.box_outline.Parent = X.cache
			end

			V, K = c[h("Box_Color")], c[h("Box_Color_2")]
			q.box_color.Thickness = math.clamp(tonumber(c[h("box_stroke_thickness")]) or 1, 1, 5)

			if V and V.Color then
				q.box_color.Color = V.Color
				local j, H = V.Color, K and K.Color or (g(0, 0, 0))

				for e, f in q.corners:GetChildren() do
