		X:connection(q.MouseButton1Click, function()
			X:ui_sound("click")
			T.open_tab()
		end)

		p = #k._subtabs == 0
		S(k._subtabs, T)

		if p then
			T.set_open(true)
		end

		return setmetatable(T, X)
	end

