	r411.findDropConst = function()
		if r411.dropProto then
			return true
		end

		if not (getgc and debug and debug.getproto and debug.getconstants and debug.setconstant) then
			return false
		end

		local function y(q, p)
			if r411.dropProto or p > 5 then
				return
			end
			local T, k = pcall(debug.getconstants, q)

			if T and type(k) == "table" then
				for T, P in next, k, nil do
					if P == -70 then
						r411.dropProto = q
						r411.dropIdx = T
						r411.dropOrig = P
						return
					end
				end
			end

			k = 1

			while true do
				local T, P = pcall(debug.getproto, q, k)
				if not T or type(P) ~= "function" then
					break
				end
				y(P, p + 1)
				if r411.dropProto then
					return
				end
				k += 1
			end
		end

		local q = _G.DELTA_HF

		if q and type(q.cbOld) == "function" then
			pcall(y, q.cbOld, 0)
			if r411.dropProto then
				return true
			end
		end

		q = r411.gameMod("Bullet")

		if q and type(rawget(q, "CreateBullet")) == "function" then
			pcall(y, rawget(q, "CreateBullet"), 0)
			if r411.dropProto then
				return true
			end
		end

		pcall(function()
			local q, p, T = next, getgc(true)

			for k, k in q, p, T do
				if type(k) == "table" and type(rawget(k, "CreateBullet")) == "function" then
					y(rawget(k, "CreateBullet"), 0)
					if r411.dropProto then
						return
					end
				end
			end
		end)

		return r411.dropProto ~= nil
	end

	r411.dropSafe = nil

	r411.dropWrite = function(y)
		local q, p = r411.dropProto, r411.dropIdx
		if not q or r411.dropSafe == false then
			return false
		end

		if r411.dropSafe then
			return (pcall(debug.setconstant, q, p, y))
		end
		local T, k = pcall(debug.getconstants, q)
		if not (T and type(k) == "table" and k[p] == r411.dropOrig) then
			r411.dropSafe = false
			return false
		end
		T = {}

		for P, h in next, k, nil do
			T[P] = h
		end

		if not pcall(debug.setconstant, q, p, y) then
			r411.dropSafe = false
			return false
		end
		k, y = pcall(debug.getconstants, q)
		if not (k and type(y) == "table") then
			r411.dropSafe = false
			return false
		end
		k = nil

		for P, h in next, y, nil do
			if T[P] ~= h then
				if k then
					k = -1
					break
				end
				k = P
			end
		end

		if k == p then
			r411.dropSafe = true
			return true
		end

		if type(k) == "number" and k > 0 and T[k] ~= nil then
			pcall(debug.setconstant, q, p, T[k])
		end

		r411.dropSafe = false
		return false
	end

	r411.setNoDrop = function(y)
