		y = 1 + h

		for C = 1, 10, 1 do
			local _, V = math.max(0, 0.2 - C * 0.02), P[C]
			V.Position = q
			V.Radius = p + C * h
			V.Color = T
			V.Transparency = _
			V.Thickness = y
			V.Visible = true
			k = P[C + 10]
			k.Position = q
			k.Radius = math.max(0, p - C * h)
