		return
	end

	T = os.clock()
	q = math.clamp(T - (r411.jumpTick or T), 0, 0.25)
	r411.jumpTick = T
	k = math.clamp(k - 10 * q, 0, 40)
	r411.jumpSpeed = k

	if P.Magnitude > 0.1 then
		q = Vector3.new(P.X, 0, P.Z)

		if q.Magnitude > 0.001 then
