					T = (q.Status.Journey.Statistics:GetAttribute("TimePlayed") or 0) / 3600
				end)

				y[#y + 1] = string.format("%.1fh", T)
			end

			if r408("inv_show_reports", false) then
				local T = 0

				pcall(function()
					local k = q.Status and (q.Status:FindFirstChild("UAC"))
					local q = k and (k:FindFirstChild("Reports"))

					if q then
						T = q:GetAttribute("1") or 0
					end
				end)

				y[#y + 1] = T .. " rep"
			end

			if r408("inv_show_team", false) then
				local q

				pcall(function()
					local T = r2_5:FindFirstChild("Clans")

					if T then
						for k, k in ipairs(T:GetChildren()) do
							if k:FindFirstChild(p) then
								q = k.Name
								break
							end
						end
					end
				end)

				y[#y + 1] = "Team: " .. (q or "none")
			end
		end

		if r408("inv_show_val", false) then
			y[#y + 1] = "~" .. r409(math.floor(P)) .. " RUB"
		end

		return {
			sections = b,
			label = h,
			labelColor = _,
			stats = table.concat(y, "  |  "),
			right = r411.invRightText(t),
		}
	end

	r411.invSetAlpha = function(C, y)
		if C._alpha == y then
			return
		end
		C._alpha = y
		C.root.BackgroundTransparency = y
		C.outline.Transparency = y
		C.innerStroke.Transparency = y
		C.topbar.BackgroundTransparency = y

		if C.glow then
			C.glow.ImageTransparency = 0.8 + 0.2 * y
		end

		for q = 1, #C.hdrs, 1 do
			C.hdrs[q].line.BackgroundTransparency = y
		end

		for q = 1, C.maxCards, 1 do
			C.cards[q].frame.BackgroundTransparency = y
		end

		for q = 1, #C.extra, 1 do
			C.extra[q].BackgroundTransparency = y
		end
	end

	r411.invRow = function(C, y, q, p, T, k, P)
		local h = C.rows[y]
		h.Text = q
		h.TextColor3 = p
		h.TextSize = P
		h.Position = UDim2.new(0, C.padX - 2, 0, T)
		h.Size = UDim2.new(1, -(C.padX * 2 - 2), 0, k)
		h.Visible = true
	end

	r411.invHeader = function(C, y, q, p, T, k)
		local P, h = C.hdrs[y], C.padX

		if q then
			P.lbl.Text = q
			P.lbl.TextSize = math.max(k - 1, 9)
			P.lbl.Position = UDim2.new(0, h, 0, p)
			P.lbl.Size = UDim2.new(1, -h * 2, 0, T)
			P.lbl.Visible = true
			P.line.Position = UDim2.new(0, h, 0, p + T - 2)
		else
			P.lbl.Visible = false
			P.line.Position = UDim2.new(0, h, 0, p + math.floor(T * 0.5))
		end

		P.line.Size = UDim2.new(1, -h * 2, 0, 1)
		P.line.Visible = true
	end

	r411.invFinish = function(y, q, p, T, k, P, h, _)
		for V = k + 1, y._rows, 1 do
			y.rows[V].Visible = false
		end

		for V = P + 1, y._hdrs, 1 do
			local J = y.hdrs[V]
			J.lbl.Visible = false
			J.line.Visible = false
		end

		for V = h + 1, y._cards, 1 do
			y.cards[V].frame.Visible = false
		end

		y._rows = k
		y._hdrs = P
		y._cards = h
		y._hidAll = false
		P = y.root

		if y._px ~= q or y._py ~= p then
			y._px = q
			y._py = p
			P.Position = UDim2.new(0, q, 0, p)
		end

		if y._goalH ~= T then
			y._goalH = T

			r401:tween(P, {
				Size = UDim2.new(0, y.w, 0, T),
			})
		end

		r411.invSetAlpha(y, math.clamp(r408("inv_bg_transparency", 15) / 100, 0, 1))

		if y.right.Text ~= _ then
			y.right.Text = _
		end

		if not P.Visible then
			P.Visible = true
		end
	end

	r411.invDrawText = function(y, q, p, T, k, P)
		local h = 0
		local _ = 0
		local V = y.titleH

		for J = 1, #q, 1 do
			if h >= y.max then
				break
			end
			local t = q[J]

			if t.header or t.isDivider then
				if _ < #y.hdrs then
					_ += 1
					r411.invHeader(y, _, t.header, V, k, P)
					V += k
				end
			else
				h += 1
				r411.invRow(y, h, t.text, t.color, V, k, P)
				V += k
			end
		end

		r411.invFinish(y, p, T, V + 4, h, _, 0, q.right or "")
	end

	r411.invDrawImage = function(y, q, p, T, k, P)
		local h = y.titleH
		local _ = 0
		local V = 0
		local J = 0

		local function t(b, R)
			if _ >= y.max then
				return
			end
			_ += 1
			r411.invRow(y, _, b, R, h, k, P)
			h += k
		end

		if q then
			t("  " .. q.label, q.labelColor)

			if q.stats ~= "" then
				t("  " .. q.stats, r419.col_kdr)
			end

			local b = q.sections

			if #b == 0 then
				t("  (empty)", r131)
			end

			local R, L, K = y.cell + y.cgap, y.cols, y.padX

			for O, F in ipairs(b) do
				if V >= #y.hdrs or J >= y.maxCards then
					break
				end
				V += 1
				r411.invHeader(y, V, F.name, h, k, P)
				h = h + k + 1
				O = 0

				for b, r in ipairs(F.entries) do
					if J >= y.maxCards then
						break
					end
					J += 1
					b = y.cards[J]
					local G, g, x, d = b.frame, UDim2.new, K + O % L * R, math.floor(O / L) * R
					G.Position = g(0, x, 0, h + d)

					if b.icon.Image ~= r.icon then
						b.icon.Image = r.icon
					end

					if r.badge then
						if b.badge.Text ~= r.badge then
							b.badge.Text = r.badge
						end

						if not b.badge.Visible then
							b.badge.Visible = true
						end
					elseif b.badge.Visible then
						b.badge.Visible = false
					end

					b.frame.Visible = true
					O += 1
				end

				F = math.ceil(O / L) * R
				h = h + F + 1
			end
		else
			t("  Preview", r419.col_header)
			V = 1
			r411.invHeader(y, V, "HOTBAR", h, k, P)
			h += k
			t("    (drag to move)", r131)
		end

		local k, P, t = r411.invFinish, h + 4, q and q.right or ""
		k(y, p, T, P, _, V, J, t)
	end

