	r411.hullHit = function(y, q, p, T)
		local k = r411.hullParams

		k.FilterDescendantsInstances = {
			r404,
			r92.LocalPlayer.Character,
			workspace:FindFirstChild("NoCollision"),
		}

		local P = workspace:Raycast(p, q - p, k)
		if P and (P.Instance:IsDescendantOf(y)) then
