r411.questMod = nil
r411.questModNext = 0

r411.questModule = function()
	local y = r411.questMod
	if y then
		return y
	end
	y = os.clock()
	if y < r411.questModNext then
		return nil
	end
	r411.questModNext = y + 5

	local q, p = pcall(function()
		local T = r2_5:FindFirstChild("Modules")
		local k = T and (T:FindFirstChild("Quests"))
		return k and (require(k))
	end)

	if q and type(p) == "table" then
		r411.questMod = p
		return p
	end

	if not q then
		r411.questModErr = tostring(p)
	else
		y = r2_5:FindFirstChild("Modules")
		r411.questModErr = y and (y:FindFirstChild("Quests")) and "require returned " .. typeof(p) or "RS.Modules.Quests not found"
	end

	return nil
end

r411.questDefs = function()
	local y = r411.questModule()
	if type(y) ~= "table" then
		return nil
	end
	local C = rawget(y, "Quests")
	if type(C) == "table" then
		return C
	end
	return y
end

r411.QPOS_KEYS = { "Position", "WorldPosition", "Pos", "Location", "TargetPosition", "QuestPosition" }
r411.QINST_KEYS = { "Part", "Object", "Marker", "Attachment", "Instance", "Target", "LocationPart" }
r411.QSKIP_KEYS = { Name = true, Description = true, Dialogue = true, EndDialogue = true, StartDialogue = true, Reward = true, Rewards = true }

r411.questPos = function(y, q)
	q = q or 0
	local p = typeof(y)
	if p == "Vector3" then
		return y
	end

	if p == "CFrame" then
		return y.Position
	end

	if p == "Instance" then
		if y:IsA("BasePart") then
			return y.Position
		end

		if y:IsA("Attachment") then
			return y.WorldPosition
		end

		if y:IsA("Model") then
			local T, k = pcall(function()
				return y:GetPivot()
			end)

			if T and k then
				return k.Position
			end
		end

		return nil
	end

	if type(y) ~= "table" or q > 4 then
		return nil
	end

	for T, k in ipairs(r411.QPOS_KEYS) do
		T = r411.questPos(y[k], q + 1)
		if T then
			return T
		end
	end

	for T, k in ipairs(r411.QINST_KEYS) do
		T = r411.questPos(y[k], q + 1)
		if T then
			return T
		end
	end

	for T, k in pairs(y) do
		if not r411.QSKIP_KEYS[T] then
			p = r411.questPos(k, q + 1)
			if p then
				return p
			end
		end
	end

	return nil
end

r411.qAttr = function(C, y)
	local q, p = pcall(C.GetAttribute, C, y)
	if q then
		return p
	end
end

r411.questObjectives = function(y)
	local q = {}
	if type(y) ~= "table" then
		return q
	end
	local p = type(y.def) == "table" and (rawget(y.def, "Objectives")) or nil
	p = if type(p) ~= "table" then nil else p

	local function T(k, P, h)
		local _ = {
			key = tostring(k),
		}

		if type(P) == "table" then
			_.type = rawget(P, "Type")
			_.desc = rawget(P, "Description")
			_.item = rawget(P, "ItemName")
			_.itemId = rawget(P, "ItemId")
			_.faction = rawget(P, "Faction")
			_.target = rawget(P, "Name")
			_.amount = tonumber(rawget(P, "Amount"))
			_.optional = rawget(P, "Optional") and true or false
			_.pos = r411.questPos(P)
		end

		if h then
			k = r411.qAttr
			_.inst = h
			_.type = k(h, "Type") or _.type
			_.desc = k(h, "Description") or _.desc
			_.item = k(h, "ItemName") or _.item
			_.itemId = k(h, "ItemId") or _.itemId
			_.faction = k(h, "Faction") or _.faction
			_.target = k(h, "Name") or _.target
			_.amount = tonumber(k(h, "Amount")) or _.amount
			P = k(h, "Optional")

			if P ~= nil then
				_.optional = P and true or false
			end

			_.carrying = k(h, "Carrying") and true or false
			_.placed = k(h, "Placed") and true or false
			_.done = (k(h, "Complete") or _.carrying or _.placed) and true or false
			_.progress = tonumber(k(h, "Progress") or (k(h, "Count")))
			_.live = true
		end

		if type(_.desc) ~= "string" then
			_.desc = nil
		end

		q[#q + 1] = _
	end

	local C, k = {}, y.entry

	if typeof(k) == "Instance" then
		for y, P in ipairs(k:GetChildren()) do
			C[P.Name] = true
			y = p and (p[P.Name] or p[tonumber(P.Name)]) or nil
			T(P.Name, y, P)
		end
	end

	if p then
		for y, k in pairs(p) do
			if not C[tostring(y)] then
				T(y, k, nil)
			end
		end
	end

	table.sort(q, function(C, y)
		return C.key < y.key
	end)

	return q
end

r411.questNeeds = function(y)
	local q = {}

	for p, T in ipairs(if type(y) == "table" and (y.entry ~= nil or y.def ~= nil or y.id ~= nil) then (r411.questObjectives(y)) else (r411.questObjectives({ def = y }))) do
		p = tostring(T.type or "")
		local C, y

		if p == "HandOver" then
			C, y = T.item, "handover"
		elseif p == "Fetch" then
			C, y = T.itemId, "fetch"
		elseif type(T.item) == "string" then
			C, y = T.item, "handover"
		end

		if type(C) == "string" and C ~= "" then
			p = nil

			for k, k in ipairs(q) do
				if k.name == C then
					p = k
					break
				end
			end

			if p then
				if T.amount then
					p.amount = math.max(p.amount or 1, T.amount)
				end

				if not T.done then
					p.done = false
				end
			else
				q[#q + 1] = {
					name = C,
					amount = T.amount,
					kind = y,
					done = T.done and true or false,
					optional = T.optional and true or false,
					key = T.key,
				}
			end
		end
	end

	return q
end

r411.qwCache = {
	t = 0,
	set = {},
	n = 0,
}

r411.questWishSet = function()
	local y, q = r411.qwCache, os.clock()
	if q - y.t < 2 then
		return y.set, y.n
	end
	y.t = q
	local q, p = {}, 0

	pcall(function()
		local T = r408("item_esp_questfuture", false)

		for k, P in pairs(r411.questItemMap()) do
			local h = #P.active

			if h > 0 or T and #P.future > 0 then
				local T = h > 0 and P.active or P.future
				p += 1

				q[k] = {
					name = P.name,
					kind = P.kind,
					tier = h > 0 and "active" or "future",
					quests = T,
					quest = T[1] and T[1].quest or nil,
					away = h > 0 and 0 or (T[1] and T[1].away or 0),
					amount = h > 0 and P.amount or T[1] and T[1].amount or nil,
					have = P.kind == "handover" and (r411.questHave(P.name)) or nil,
					done = false,
				}
			end
		end
	end)

	y.set = q
	y.n = p
	return q, p
end

r411.questWishHit = function(y)
	if not r408("item_esp_questwish", false) then
		return nil
	end
	return r411.questWishSet()[string.lower(r411.itemBase(tostring(y)))]
end

r411.qkCache = { t = 0, set = nil }

r411.questKills = function()
	local y, q = r411.qkCache, os.clock()
	if y.set and q - y.t < 2 then
		return y.set
	end
	y.t = q

	local q = {
		n = 0,
		any = false,
		factions = {},
		names = {},
	}

	pcall(function()
		for p, T in ipairs(r411.activeQuests()) do
			for k, P in ipairs(r411.questObjectives(T)) do
				if tostring(P.type) == "Elimination" and not P.done then
					q.n = q.n + 1
					k, p = P.target, P.faction

					if type(k) == "string" and k ~= "" then
						q.names[string.lower(k)] = true
					elseif type(p) == "string" and p ~= "" then
						if p == "Any" then
							q.any = true
						else
							q.factions[string.lower(p)] = true
						end
					else
						q.any = true
					end
				end
			end
		end
	end)

	y.set = q
	return q
end

r411.qkTagCache = { t = 0, s = "(Q) " }

r411.questKillTag = function()
	local y, q = r411.qkTagCache, os.clock()
	if q - y.t < 1 then
		return y.s
	end
	local p = r411.tint
	if not p then
		return "(Q) "
	end
	y.t = q
	local q, T = r411.wcol("quest_kill_color", Color3.fromRGB(255, 235, 90))
	y.s = p("(Q)", q, T) .. " "
	return y.s
end

r411.questKillHit = function(y)
	if not (y and (r408("quest_kill_tag", true))) then
		return false
	end
	local q = r411.questKills()
	if not q or q.n == 0 then
		return false
	end

	if q.names[string.lower(y.Name)] then
		return true
	end

	if q.any then
		return true
	end
	local p = r411.qAttr(y, "Faction")
	return q.factions[string.lower(if type(p) ~= "string" or p == "" then "Wastelanders" else p)] == true
end

r411.questCache = {
	t = 0,
	list = {},
}

r411.activeQuests = function()
	local y, q = r411.questCache, os.clock()
	if q - y.t < 2 then
		return y.list
	end
	y.t = q
	local q = {}

	pcall(function()
		local p = r2_5:FindFirstChild("Players")
		local T = p and (p:FindFirstChild(r92.LocalPlayer.Name))
		p = T and (T:FindFirstChild("Status"))
		T = p and (p:FindFirstChild("Journey"))
		p = T and (T:FindFirstChild("Quests"))
		if not p then
			return
		end
		T = r411.questDefs()
		local k = r408("quest_hide_complete", true)

		for P, h in ipairs(p:GetChildren()) do
			P = h:GetAttribute("State")

			if not (k and P == "Complete") then
				local p = type(T) == "table" and T[h.Name] or nil
				local T = type(p) == "table" and (rawget(p, "Name")) or nil

				q[#q + 1] = {
					id = h.Name,
					label = type(T) == "string" and T ~= "" and T or h.Name,
					state = type(P) == "string" and P ~= "" and P or "Active",
					def = p,
					entry = h,
					pos = p and (r411.questPos(p)) or nil,
				}
			end
		end

		table.sort(q, function(C, p)
			return C.label < p.label
		end)
	end)

	y.list = q
	return q
end

r411.qiCache = {
	t = 0,
	list = {},
}

r411.questItemList = function()
	local y, q = r411.qiCache, os.clock()
	if q - y.t < 1 then
		return y.list
	end
	y.t = q
	local C = {}

	pcall(function()
		local q = workspace:FindFirstChild("QuestItems")
		if not q then
			return
		end

		for p, T in ipairs(q:GetChildren()) do
			p = if T:IsA("Model") then T.PrimaryPart or (T:FindFirstChildWhichIsA("BasePart")) else if T:IsA("BasePart") then T else nil

			if p and p.Transparency < 1 then
				local q, k = T:GetAttribute("DisplayName"), T:GetAttribute("ItemId")

				C[#C + 1] = {
					model = T,
					anchor = p,
					raw = T.Name,
					itemId = type(k) == "string" and k ~= "" and k or nil,
					label = type(q) == "string" and q ~= "" and q or T.Name,
				}
			end
		end
	end)

	y.list = C
	return C
end

r411.questNearest = function(y)
	local q = string.lower(r411.itemBase(tostring(y)))
	local p, T = r404.CFrame.Position

	local function k(P)
		local h = p - P
		P = h.X * h.X + h.Y * h.Y + h.Z * h.Z
		h = not T or P < T

		if h then
			T = P
		end
	end

	for p, p in ipairs(r411.questItemList()) do
		if p.anchor.Parent and (string.lower(r411.itemBase(p.label)) == q or p.raw and string.lower(p.raw) == q or p.itemId and string.lower(p.itemId) == q) then
			k(p.anchor.Position)
		end
	end

	y = r411.getDropped

	if y then
		for p, p in ipairs(y()) do
			if p.anchor.Parent and string.lower(r411.itemBase(p.name)) == q then
				k(p.anchor.Position)
			end
		end
	end

	return T and (math.sqrt(T)) or nil
end

r411.carryCache = { t = 0, map = nil }

r411.carryInterval = function()
	local y = tonumber(r408("quest_cache_interval", 1))
	return if not y or y < 0.25 then 0.25 else y
end

r411.carryBust = function()
	r411.carryCache.map = nil
end

r411.carryCounts = function()
	local y, q = r411.carryCache, os.clock()
	if y.map and not (r408("quest_cache_auto", true) and q - y.t >= r411.carryInterval()) then
		return y.map
	end
	y.t = q
	local q, p = {}, false

	pcall(function()
		local T = r2_5:FindFirstChild("Players")
		local k = T and (T:FindFirstChild(r92.LocalPlayer.Name))
		if not k then
			return
		end
		p = true

		local function T(P, h)
			if not P or h > 5 then
				return
			end

			for _, _ in ipairs(P:GetChildren()) do
				local P, V = string.lower(r411.itemBase(_.Name)), _:GetAttribute("Amount")
				q[P] = (q[P] or 0) + (type(V) == "number" and V > 1 and (math.floor(V)) or 1)
				T(_:FindFirstChild("Inventory"), h + 1)
			end
		end

		T(k:FindFirstChild("Inventory"), 0)
		T(k:FindFirstChild("Hotbar"), 0)
	end)

	if not p then
		return y.map or q
	end
	y.map = q
	return q
end

r411.questHave = function(y)
	local q = string.lower(r411.itemBase(tostring(y)))
	local p, T = r411.carryCounts()[q] or 0, 0

	pcall(function()
		T = r411.vaultHas(y)
	end)

	return p + T, p, T
end

r411.qsCache = { built = false, defs = nil, byId = nil, order = nil }

r411.questStatic = function()
	local y, q = r411.qsCache, r411.questDefs()
	if y.built and q == y.defs then
		return y
	end

	if type(q) ~= "table" then
		return y
	end
	local p, T = {}, {}

	for k, P in pairs(q) do
		if type(P) == "table" and type(rawget(P, "Objectives")) == "table" then
			local h, _, V = rawget(P, "Name"), rawget(P, "RequiredQuests"), tostring(k)

			local k = {
				id = V,
				label = type(h) == "string" and h ~= "" and h or V,
				def = P,
				giver = rawget(P, "QuestGivenBy"),
				story = rawget(P, "Story"),
				brief = rawget(P, "Description"),
				image = rawget(P, "Image"),
				rewards = rawget(P, "Rewards"),
				extra = rawget(P, "AdditionalRewardsText"),
				badge = tonumber(rawget(P, "Achievement")),
				requires = type(_) == "table" and _ or {},
				pos = r411.questPos(P),
				q = {},
				needs = r411.questNeeds({ def = P }),
			}

			p[V] = k
			T[#T + 1] = k
		end
	end

	if #T == 0 then
		return y
	end
	y.built = true
	y.defs = q
	y.byId = p
	y.order = T
	return y
end

r411.qxCache = { t = 0, list = nil, byId = nil }

r411.questIndex = function()
	local y, q = r411.qxCache, os.clock()
	if y.list and q - y.t < 3 then
		return y.list, y.byId
	end
	y.t = q
	local q = r411.questStatic()

	if not q.built then
		y.list = y.list or {}
		y.byId = y.byId or {}
		return y.list, y.byId
	end

	local p = y.list

	if p then
		table.clear(p)
	else
		p = {}
		y.list = p
	end

	local T = y.byId

	if T then
		table.clear(T)
	else
		T = {}
		y.byId = T
	end

	pcall(function()
		local y = r2_5:FindFirstChild("Players")
		local k = y and (y:FindFirstChild(r92.LocalPlayer.Name))
		y = k and (k:FindFirstChild("Status"))
		k = y and (y:FindFirstChild("Journey"))
		y = k and (k:FindFirstChild("Quests")) or nil

		for P = 1, #q.order, 1 do
			k = q.order[P]
			P = k.q
			P.id, P.label, P.def = k.id, k.label, k.def
			P.giver, P.story = k.giver, k.story
			P.brief, P.image = k.brief, k.image
			P.rewards, P.requires = k.rewards, k.requires
			P.pos, P.extra = k.pos, k.extra
			P.badge = k.badge
			local q = y and (y:FindFirstChild(k.id)) or nil
			local y = q and (q:GetAttribute("State")) or nil
			P.entry = q
			P.started = q ~= nil
			P.state = type(y) == "string" and y ~= "" and y or (q and "Active" or nil)
			P.done = P.state == "Complete"
			P.active = P.started and not P.done
			P._away = nil
			P._blockers = nil
			P.needs = q and (r411.questNeeds(P)) or k.needs
			p[#p + 1] = P
			T[P.id] = P
		end

		local C = {}

		local function y(q)
			if q.done then
				return 0
			end

			if q._away then
				return q._away
			end

			if C[q.id] then
				return 0
			end
			C[q.id] = true
			local k, P = {}, 0

			for h, _ in ipairs(q.requires) do
				h = T[tostring(_)]

				if h then
					if not h.done then
						P = P + 1 + y(h)
						k[#k + 1] = h
					end
				elseif type(_) == "string" and _ ~= "" then
					P += 1
					k[#k + 1] = { id = _, label = _, unknown = true }
				end
			end

			C[q.id] = nil
			q._away = P
			q._blockers = k
			return P
		end

		for C, C in ipairs(p) do
			y(C)
		end

		for C, C in ipairs(p) do
			C.away = C._away or 0
			C.blockers = C._blockers or {}
			C.available = not C.started and C.away == 0
			C.locked = not C.started and C.away > 0
		end

		table.sort(p, function(C, y)
			local q, k = C.active and 0 or (C.available and 1 or (C.done and 3 or 2)), y.active and 0 or (y.available and 1 or (y.done and 3 or 2))
			if q ~= k then
				return q < k
			end

			if q == 2 and C.away ~= y.away then
				return C.away < y.away
			end
			return C.label < y.label
		end)
	end)

	return p, T
end

r411.questReady = function(y)
	if type(y) ~= "table" or y.state ~= "Active" then
		return false
	end
	local q = r411.questObjectives(y)
	if #q == 0 then
		return false
	end

	for C = 1, #q, 1 do
		y = q[C]
		if not y.optional and not (y.live and y.done) then
			return false
		end
	end

	return true
end

r411.questBoardBusy = false

r411.questBoard = function(y)
	y = y or {}
	if r411.questBoardBusy then
		return nil, "already running"
	end

	if not r411.inMetro() then
		return nil, "not in the Metro (" .. r411.mapLabel() .. ")"
	end
	local q = r411.questModule()

	if type(q) ~= "table" or type(rawget(q, "new")) ~= "function" or type(rawget(q, "complete")) ~= "function" then
		q = nil
	end

	local p

	pcall(function()
		local T = r2_5:FindFirstChild("Remotes")
		p = T and (T:FindFirstChild("QuestUpdate")) or nil
	end)

	if not q and not p then
		return nil, "QuestUpdate not reachable"
	end

	local function T(k, P)
		local h, _

		if q then
			if k == "Activate" then
				h, _ = pcall(q.new, P)
			elseif k == "Complete" then
				h, _ = pcall(q.complete, q, P)
			else
				h, _ = pcall(q.handOver, q, P)
			end
		else
			h, _ = pcall(function()
				return p:InvokeServer(k, P)
			end)
		end

		return h and _ and true or false
	end

	local q, p = y.accept ~= false, y.complete ~= false

	local k, P, h = tonumber(y.passes) or (p and 4 or 1), tonumber(y.gap) or 0.2, {
		accepted = {},
		completed = {},
		handed = {},
		refused = {},
	}

	r411.questBoardBusy = true

	pcall(function()
		local function _(V)
			r411.qxCache.t = 0
			local J, t = {}, r411.questIndex()

			for b = 1, #t, 1 do
				local R = t[b]

				if V(R) then
					J[#J + 1] = {
						id = R.id,
						label = R.label or R.id,
						giver = R.giver,
					}
				end
			end

			return J
		end

		for V = 1, k, 1 do
			V = false

			if y.handover then
				local y = {}

				local function k(J)
					if J.state ~= "Active" or type(J.giver) ~= "string" then
						return false
					end

					for t, t in ipairs(r411.questObjectives(J)) do
						if tostring(t.type) == "HandOver" and t.live and not t.done then
							return true
						end
					end

					return false
				end

				for J, J in ipairs((_(k))) do
					if not y[J.giver] then
						y[J.giver] = true

						if T("HandOver", J.giver) then
							h.handed[#h.handed + 1] = J.giver
							V = true
						end

						task.wait(P)
					end
				end
			end

			if p then
				for y, p in ipairs((_(r411.questReady))) do
					local k, k = r411.questIndex()
					y = k[p.id]

					if y and (r411.questReady(y)) then
						if T("Complete", p.id) then
							h.completed[#h.completed + 1] = p.label
							V = true
						else
							h.refused[#h.refused + 1] = "turn in " .. p.label
						end

						task.wait(P)
					end
				end
			end

			if q then
				local function y(q)
					return q.available
				end

				for q, p in ipairs((_(y))) do
					local y, y = r411.questIndex()
					q = y[p.id]

					if q and q.available then
						if T("Activate", p.id) then
							h.accepted[#h.accepted + 1] = p.label
							V = true
						else
							h.refused[#h.refused + 1] = "accept " .. p.label
						end

						task.wait(P)
					end
				end
			end

			if not V then
				break
			end
			task.wait(0.4)
		end
	end)

	r411.questBoardBusy = false
	return h
end

r411.vendorMod = nil
r411.vendorModNext = 0

r411.vendorTable = function()
	local y = r411.vendorMod
	if type(y) == "table" then
		return y
	end
	y = os.clock()
	if y < r411.vendorModNext then
		return nil
	end
	r411.vendorModNext = y + 5

	pcall(function()
		local y = r2_5:FindFirstChild("Modules")
		local q = y and (y:FindFirstChild("UniversalTables"))
		if not (q and (q:IsA("ModuleScript"))) then
			return
		end
		local y, p = pcall(require, q)
		q = y and type(p) == "table" and p.UniversalTable and p.UniversalTable.Vendor or nil

		if type(q) == "table" then
			r411.vendorMod = q
		end
	end)

	return r411.vendorMod
end

r411.fmtNum = function(C)
	local y, q = tostring(math.floor(tonumber(C) or 0)), ""

	if string.sub(y, 1, 1) == "-" then
		q, y = "-", (string.sub(y, 2))
	end

	while true do
		C = nil
		y, C = string.gsub(y, "^(%d+)(%d%d%d)", "%1,%2")
		if C == 0 then
			break
		end
	end

	return q .. y
end

r411.itemProps = function(y)
	local q = r2_5:FindFirstChild("ItemsList")
	local C = q and (q:FindFirstChild(tostring(y)))
	return C and (C:FindFirstChild("ItemProperties")) or nil
end

r411.itemIcon = function(y)
	local q = r411.itemProps(y)
	y = q and (q:FindFirstChild("ItemIcon"))
	return y and y.Image or ""
end

r411.itemLabel = function(y)
	local q = r411.itemProps(y)
	local C = q and (q:GetAttribute("ItemName"))
	C = if type(C) ~= "string" or C == "" then q and (q:GetAttribute("CallSign")) else C
	return type(C) == "string" and C ~= "" and C or (tostring(y))
end

r411.vendorLabel = function(y)
	local q = r411.vendorModel(y)
	local C = q and (q:GetAttribute("DisplayName"))
	if type(C) == "string" and C ~= "" then
		return C
	end
	return (string.gsub(tostring(y), "(%l)(%u)", "%1 %2"))
end

r411.vendorReqs = function(y, q)
	if type(q) ~= "table" then
		return nil
	end

	if type(q.Requirements) == "table" then
		return q.Requirements
	end
	local p = q.Receive
	if type(p) ~= "table" or type(p.Material) ~= "string" then
		return nil
	end
	local q

	pcall(function()
		local T = r411.itemProps(p.Material)
		local k, P, h = T and (T:GetAttribute("Price")), T and (T:GetAttribute("ItemType")), r411.vendorTable()
		T = h and h[y] and h[y].TradeItemTypes
		h = T and P and T[P] and T[P].Sell
		if type(k) ~= "number" or type(h) ~= "number" then
			return
		end

		q = {
			{
				Material = "Rubles",
				Cost = math.ceil(k * (tonumber(p.Amount) or 1) * h),
			},
		}
	end)

	return q
end

r411.vendorLocked = function(y)
	local q = type(y) == "table" and y.RequiredQuest
	if type(q) ~= "string" or q == "" then
		return false, nil
	end
	local y = false

	pcall(function()
		local p = r2_5:FindFirstChild("Players")
		local T = p and (p:FindFirstChild(r92.LocalPlayer.Name))
		p = T and (T:FindFirstChild("Status"))
		T = p and (p:FindFirstChild("Journey"))
		p = T and (T:FindFirstChild("Quests"))
		T = p and (p:FindFirstChild(q))
		y = T ~= nil and T:GetAttribute("State") == "Complete"
	end)

	return not y, q
end

r411.vendorModelCache = {}
r411.vendorModelAt = 0

r411.vendorModel = function(y)
	local q = r411.vendorModelCache[y]
	if q and q.Parent then
		return q
	end
	q = os.clock()
	if q - r411.vendorModelAt < 3 then
		return nil
	end
	r411.vendorModelAt = q
	local p = r411.vendorTable()
	if not p then
		return nil
	end

	pcall(function()
		for T, T in ipairs(workspace:GetDescendants()) do
			if T:IsA("Model") and p[T.Name] and (T.PrimaryPart or (T:FindFirstChildWhichIsA("BasePart"))) then
				r411.vendorModelCache[T.Name] = T
			end
		end
	end)

	q = r411.vendorModelCache[y]
	return q and q.Parent and q or nil
end

r411.vendorNames = function()
	local y, q = r411.vendorTable(), {}
	if not y then
		return q
	end

	for C, p in pairs(y) do
		if type(p) == "table" and type(p.Items) == "table" and type(p.Items.Selling) == "table" and (next(p.Items.Selling)) then
			q[#q + 1] = C
		end
	end

	table.sort(q)
	return q
end

r411.vendorStock = function(y)
	local q = {}
	local p = r411.vendorTable()
	local T = p and p[y]
	p = T and type(T.Items) == "table" and T.Items.Selling
	if type(p) ~= "table" then
		return q
	end
	T = r411.carryCounts()

	for k, P in pairs(p) do
		if type(P) == "table" then
			local p = type(P.Receive) == "table" and P.Receive or nil
			local h, _, V, J = p and type(p.Material) == "string" and p.Material or k, r411.vendorReqs(y, P), r411.vendorLocked(P)
			local y, P = true

			if _ then
				local t = {}

				for b, R in ipairs(_) do
					b = math.floor(tonumber(R.Cost) or 0)
					y = if (T[string.lower(r411.itemBase(tostring(R.Material)))] or 0) < b then false else y
					t[#t + 1] = R.Material == "Rubles" and r411.fmtNum(b) .. "R" or b .. "x " .. r411.itemLabel(R.Material)
				end

				P = (table.concat(t, " + "))
			else
				y, P = true, "?"
			end

			q[#q + 1] = {
				key = k,
				mat = h,
				label = r411.itemLabel(h),
				icon = r411.itemIcon(h),
				amount = math.floor(p and (tonumber(p.Amount)) or 1),
				cost = P,
				reqs = _,
				locked = V,
				quest = J,
				afford = y,
			}
		end
	end

	table.sort(q, function(C, y)
		if C.locked ~= y.locked then
			return not C.locked
		end
		return C.label < y.label
	end)

	return q
end

r411.vendorBuyBusy = false

r411.vendorBuy = function(y, q)
	if r411.vendorBuyBusy then
		return nil, "already buying"
	end

	if not r411.atVendorMap() then
		return nil, "no vendors here (" .. r411.mapLabel() .. ")"
	end
	local p = r411.vendorModel(y)
	if not p then
		return nil, y .. " is not loaded in"
	end
	local y

	pcall(function()
		local T = r2_5:FindFirstChild("Remotes")
		y = T and (T:FindFirstChild("Vendor")) or nil
	end)

	if not y then
		return nil, "Vendor remote not reachable"
	end
	r411.vendorBuyBusy = true

	local T, k, P = pcall(function()
		return y:InvokeServer({ Action = "Selling", Vendor = p, ItemName = q })
	end)

	r411.vendorBuyBusy = false
	r411.carryBust()
	if not T then
		return nil, tostring(k)
	end

	if not k then
		return nil, type(P) == "string" and P or "refused"
	end
	return true, type(P) == "string" and P or nil
end

r411.instProps = function(C)
	local y = C and (C:IsA("ObjectValue")) and C.Value
	return y and (y:FindFirstChild("ItemProperties")) or nil
end

r411.sellPrice = function(q, p, T)
	T = T or 0
	if T > 3 then
		return 0, nil
	end
	local k = r411.instProps(q)
	local P = k and (k:GetAttribute("Price"))
	if type(P) ~= "number" then
		return 0, "Not interested"
	end
	local h = r411.vendorTable()
	local _ = h and h[p]
	local V = _ and _.TradeItemTypes
	h = V and V[k:GetAttribute("ItemType")]
	if not h then
		return 0, "Not interested"
	end
	local J, t = q:GetAttribute("Durability"), k:GetAttribute("OriginalMaxDurability")
	k = if type(J) == "number" and type(t) == "number" and t > 0 then J / t else 1
	if k < (tonumber(h.Durability) or 0) then
		return 0, "Durability low"
	end
	local J, b = P * k * (tonumber(q:GetAttribute("Amount")) or 1) * (tonumber(h.Buy) or 0), q:FindFirstChild("LoadedAmmo")

	if b and V.Ammo then
		for P, P in ipairs(b:GetChildren()) do
			pcall(function()
				local b = r411.itemProps(P:GetAttribute("AmmoType"))
				local R = b and (b:GetAttribute("Price"))
				b = type(R)

				if b == "number" then
					J += R * (tonumber(P:GetAttribute("Amount")) or 0) * (tonumber(V.Ammo.Buy) or 0)
				end
			end)
		end
	end

	t = q:FindFirstChild("Attachments")

	if t then
		h, _ = ipairs, table.pack(t:GetChildren())

		for q, q in h(unpack(_, 1, _.n)) do
			k = r411.sellPrice(q, p, T + 1) or 0
			J += k
		end
	end

	return J, nil
end

r411.INV_DEPTH = 4

r411.invItems = function(y, q, p)
	q, p = q or {}, p or 0
	if not y then
		return q
	end

	for T, k in ipairs(y:GetChildren()) do
		if k:IsA("ObjectValue") then
			local y, P = 0, k:FindFirstChild("Inventory")

			if P and p < r411.INV_DEPTH then
				T = #q
				r411.invItems(P, q, p + 1)
				y = #q - T
			end

			q[#q + 1] = { inst = k, depth = p, held = y }
		end
	end

	return q
end

r411.sellList = function(y)
	local q = {}

	pcall(function()
		local p = r2_5:FindFirstChild("Players")
		local T = p and (p:FindFirstChild(r92.LocalPlayer.Name))
		p = T and (T:FindFirstChild("Inventory"))
		if not p then
			return
		end

		for k, P in ipairs(r411.invItems(p)) do
			T = P.inst

			if r411.instProps(T) then
				local p, h = r411.sellPrice(T, y, 0)
				k = T.Value and T.Value.Name or T.Name

				q[#q + 1] = {
					inst = T,
					label = r411.itemLabel(k),
					icon = r411.itemIcon(k),
					amount = math.floor(tonumber(T:GetAttribute("Amount")) or 1),
					price = math.floor(p or 0),
					reason = h,
					depth = P.depth,
					held = P.held,
				}
			end
		end
	end)

	table.sort(q, function(C, y)
		if C.reason ~= nil ~= (y.reason ~= nil) then
			return C.reason == nil
		end

		if C.held > 0 ~= (y.held > 0) then
			return y.held > 0
		end

		if C.price ~= y.price then
			return C.price > y.price
		end
		return C.label < y.label
	end)

	return q
end

r411.vendorSell = function(y, q)
	if r411.vendorBuyBusy then
		return nil, "busy"
	end

	if not r411.atVendorMap() then
		return nil, "no vendors here (" .. r411.mapLabel() .. ")"
	end

	if not (q and q.Parent) then
		return nil, "item is gone"
	end
	local p = r411.vendorModel(y)
	if not p then
		return nil, y .. " is not loaded in"
	end
	local y

	pcall(function()
		local T = r2_5:FindFirstChild("Remotes")
		y = T and (T:FindFirstChild("Vendor")) or nil
	end)

	if not y then
		return nil, "Vendor remote not reachable"
	end
	r411.vendorBuyBusy = true

	local T, k, P = pcall(function()
		return y:InvokeServer({
			Action = "Buying",
			Vendor = p,
			TradeList = { q },
		})
	end)

	r411.vendorBuyBusy = false
	r411.carryBust()
	if not T then
		return nil, tostring(k)
	end

	if not k then
		return nil, type(P) == "string" and P or "refused"
	end
	return true, type(P) == "string" and P or nil
end

r411.AB_FLAG = "market_autobuy"

r411.abList = function()
	local y = {}
	local q = r403[r411.AB_FLAG]
	if type(q) ~= "string" or q == "" then
		return y
	end

	for C in string.gmatch(q, "[^;]+") do
		local q, p, T = string.match(C, "^([^|]+)|([^|]+)|(%d+)$")
		C = tonumber(T)

		if q and p and C and C > 0 then
			y[#y + 1] = {
				vendor = q,
				key = p,
				want = math.floor(C),
			}
		end
	end

	return y
end

r411.abWant = function(y, q)
	for p, p in ipairs(r411.abList()) do
		if p.vendor == y and p.key == q then
			return p.want
		end
	end

	return 0
end

r411.abSet = function(y, q, p)
	p = math.clamp(math.floor(tonumber(p) or 0), 0, 99)
	local T, k = r411.abList(), false

	for P = #T, 1, -1 do
		local h = T[P]

		if h.vendor == y and h.key == q then
			if p == 0 then
				table.remove(T, P)
			else
				h.want = p
			end

			k = true
		end
	end

	if not k and p > 0 then
		T[#T + 1] = { vendor = y, key = q, want = p }
	end

	y = {}

	for q, q in ipairs(T) do
		y[#y + 1] = q.vendor .. "|" .. q.key .. "|" .. q.want
	end

	r403[r411.AB_FLAG] = table.concat(y, ";")
	return p
end

r411.abCooldown = {}

r411.abStep = function()
	if not r411.atVendorMap() then
		return nil, "no vendors here"
	end

	if r411.vendorBuyBusy then
		return nil, "busy"
	end
	local y, q = os.clock(), {}

	for p, T in ipairs(r411.abList()) do
		p = r411.abCooldown[T.vendor .. "|" .. T.key]

		if not (p and y < p) then
			q[T.vendor] = q[T.vendor] or {}
			table.insert(q[T.vendor], T)
		end
	end

	local p = r411.carryCounts()

	for T, k in pairs(q) do
		if r411.vendorModel(T) then
			local q = {}

			for P, P in ipairs((r411.vendorStock(T))) do
				q[P.key] = P
			end

			for P, h in ipairs(k) do
				P = q[h.key]

				if P and not P.locked then
					if (p[string.lower(r411.itemBase(P.mat))] or 0) < h.want then
						if not P.afford then
							r411.abCooldown[T .. "|" .. h.key] = y + 30
						else
							local q, p = r411.vendorBuy(T, h.key)
							if not q then
								r411.abCooldown[T .. "|" .. h.key] = y + 30
								return nil, p
							end

							return {
								vendor = T,
								key = h.key,
								label = P.label,
								amount = P.amount,
							}
						end
					end
				end
			end
		end
	end

	return nil, nil
end

r411.sellTypesCache = nil

r411.sellTypes = function()
	if r411.sellTypesCache then
		return r411.sellTypesCache
	end
	local y, q, p = r411.vendorTable(), {}, {}
	if not y then
		return p
	end

	for T, k in pairs(y) do
		if type(k) == "table" and type(k.TradeItemTypes) == "table" then
			for y, P in pairs(k.TradeItemTypes) do
				if type(P) == "table" then
					local k = q[y]

					if not k then
						k = {
							type = y,
							vendors = {},
						}

						q[y] = k
						p[#p + 1] = k
					end

					k.vendors[#k.vendors + 1] = {
						name = T,
						buy = tonumber(P.Buy) or 0,
					}
				end
			end
		end
	end

	for y, y in ipairs(p) do
		table.sort(y.vendors, function(y, q)
			if y.buy ~= q.buy then
				return y.buy > q.buy
			end
			return y.name < q.name
		end)
	end

	table.sort(p, function(y, q)
		return y.type < q.type
	end)

	r411.sellTypesCache = p
	return p
end

r411.AS_FLAG = "market_autosell"

r411.asMap = function()
	local y = {}
	local q = r403[r411.AS_FLAG]
	if type(q) ~= "string" or q == "" then
		return y
	end

	for C in string.gmatch(q, "[^;]+") do
		local q, p = string.match(C, "^([^|]+)|([^|]+)$")

		if q and p then
			y[q] = p
		end
	end

	return y
end

r411.asSet = function(y, q)
	local p = r411.asMap()
	p[y] = q
	y = {}

	for q, T in pairs(p) do
		if T then
			y[#y + 1] = q .. "|" .. T
		end
	end

	table.sort(y)
	r403[r411.AS_FLAG] = table.concat(y, ";")
end

r411.sellItemCache = {}

r411.sellItems = function(y)
	local q = r411.sellItemCache[y]
	if q then
		return q
	end
	q = r411.vendorTable()
	local p = q and q[y]
	local T = type(p) == "table" and p.TradeItemTypes or nil
	q = r2_5:FindFirstChild("ItemsList")
	if type(T) ~= "table" or not q then
		return {}
	end
	p = {}

	for k, P in ipairs(q:GetChildren()) do
		if r411.itemBase(P.Name) == P.Name then
			k = P:FindFirstChild("ItemProperties")
			local q = k and (k:GetAttribute("ItemType"))

			if q and T[q] then
				local T = k:GetAttribute("ItemName")
				T = if type(T) ~= "string" or T == "" then (k:GetAttribute("CallSign")) else T
				local h = k:FindFirstChild("ItemIcon")

				p[#p + 1] = {
					name = P.Name,
					key = string.lower(P.Name),
					type = q,
					label = type(T) == "string" and T ~= "" and T or P.Name,
					icon = (if h and not (h:IsA("ImageLabel") or (h:IsA("ImageButton"))) then nil else h) and (if h and not (h:IsA("ImageLabel") or (h:IsA("ImageButton"))) then nil else h).Image or "",
				}
			end
		end
	end

	table.sort(p, function(q, T)
		if q.type ~= T.type then
			return q.type < T.type
		end
		return q.label < T.label
	end)

	if #p > 0 then
		r411.sellItemCache[y] = p
	end

	return p
end

r411.ASI_FLAG = "market_autosell_items"

r411.asiMap = function()
	local y = {}
	local q = r403[r411.ASI_FLAG]
	if type(q) ~= "string" or q == "" then
		return y
	end

	for C in string.gmatch(q, "[^;]+") do
		local q, p = string.match(C, "^([^|]+)|([^|]+)$")

		if q and p then
			y[q] = p
		end
	end

	return y
end

r411.asiSet = function(y, q)
	local p = r411.asiMap()
	p[string.lower(tostring(y))] = q
	y = {}

	for q, T in pairs(p) do
		if T then
			y[#y + 1] = q .. "|" .. T
		end
	end

	table.sort(y)
	r403[r411.ASI_FLAG] = table.concat(y, ";")
end

r411.asRoute = function(y, q)
	q = if q == nil then r411.asMap()[y] else q
	if not q or q == "-" then
		return nil
	end

	for p, p in ipairs(r411.sellTypes()) do
		if p.type == y then
			if q ~= "*" then
				for y, y in ipairs(p.vendors) do
					if y.name == q and (r411.vendorModel(q)) then
						return q
					end
				end

				return nil
			end

			for y, y in ipairs(p.vendors) do
				if r411.vendorModel(y.name) then
					return y.name
				end
			end

			return nil
		end
	end

	return nil
end

r411.asStep = function()
	if not r411.atVendorMap() then
		return nil, "no vendors here"
	end

	if r411.vendorBuyBusy then
		return nil, "busy"
	end
	local y, q = r411.asMap(), r411.asiMap()
	if not (next(y) or (next(q))) then
		return nil, nil
	end
	local p = {}

	for T, k in ipairs(r411.abList()) do
		T = r411.vendorTable()
		local P = T and T[k.vendor] and T[k.vendor].Items and T[k.vendor].Items.Selling
		T = P and P[k.key]
		P = type(T) == "table" and type(T.Receive) == "table" and T.Receive.Material or k.key
		p[string.lower(r411.itemBase(tostring(P)))] = true
	end

	local T

	pcall(function()
		local k = r2_5:FindFirstChild("Players")
		local P = k and (k:FindFirstChild(r92.LocalPlayer.Name))
		T = P and (P:FindFirstChild("Inventory")) or nil
	end)

	if not T then
		return nil, nil
	end

	for k, P in ipairs(r411.invItems(T)) do
		k = P.inst
		local T = r411.instProps(k)
		local h = P.held == 0 and T and (T:GetAttribute("ItemType")) or nil

		if h then
			T = k.Value and k.Value.Name or k.Name
			P = string.lower(r411.itemBase(T))
			local _ = q[P]
			_ = if _ == "-" then nil else if _ == nil then y[h] else _

			if _ and not p[P] then
				local y = r411.asRoute(h, _)

				if y then
					local q, p = r411.sellPrice(k, y, 0)

					if not p and q > 0 then
						local p, P, h = r411.itemLabel(T), r411.vendorSell(y, k)
						if not P then
							return nil, h
						end

						return {
							vendor = y,
							label = p,
							price = math.floor(q),
						}
					end
				end
			end
		end
	end

	return nil, nil
end

r411.CFG_KINDS = {
	autobuy = {
		store = "market_ab_cfgs",
		sel = "market_ab_cfg",
		file = "Autobuy",
		flags = { "market_autobuy" },
	},
	autosell = {
		store = "market_as_cfgs",
		sel = "market_as_cfg",
		file = "Autosell",
		flags = { "market_autosell", "market_autosell_items" },
	},
}

r411.CFG_MAX = 24

r411.cfgName = function(C)
	C = string.gsub(tostring(C or ""), "%c", " ")
	C = string.gsub(C, "[<>:\"/\\|%?%*]", "")
	C = string.gsub(C, "%s+", " ")
	C = string.gsub(C, "^%s+", "")
	C = string.gsub(C, "%s+$", "")
	C = if string.match(C, "^%.+$") then "" else C
	return if #C > 24 then (string.gsub(string.sub(C, 1, 24), "%s+$", "")) else C
end

r411.cfgDir = function()
	local y = r401:config_dir() .. "/Auto-Configs"

	pcall(function()
		if isfolder and not isfolder(y) then
			makefolder(y)
		end
	end)

	return y
end

r411.cfgPath = function(y, q)
	local p = r411.CFG_KINDS[y]
	if not p then
		return nil
	end
	return r411.cfgDir() .. "/" .. p.file .. "-" .. q .. ".cfg"
end

r411.cfgList = function(y)
	local q = {}
	local p = r411.CFG_KINDS[y]
	if not p then
		return q
	end
	local T, k = pcall(listfiles, r411.cfgDir())
	if not (T and type(k) == "table") then
		return q
	end
	T = string.lower(p.file) .. "-"

	for C, P in ipairs(k) do
		C = string.match(tostring(P), "[^/\\]+$") or (tostring(P))
		p = string.lower(C)

		if string.sub(p, 1, #T) == T and string.sub(p, -4) == ".cfg" then
			y = string.sub(C, #T + 1, -5)

			if y ~= "" then
				local C, p = pcall(readfile, tostring(P))

				q[#q + 1] = {
					name = y,
					data = C and type(p) == "string" and p or "",
				}
			end
		end
	end

	table.sort(q, function(C, y)
		return string.lower(C.name) < string.lower(y.name)
	end)

	return q
end

r411.cfgWrite = function(y, q)
	if not r411.CFG_KINDS[y] then
		return
	end
	local p = {}

	for T, T in ipairs(q) do
		if T.name and T.name ~= "" then
			p[string.lower(T.name)] = true
			pcall(writefile, r411.cfgPath(y, T.name), T.data or "")
		end
	end

	for q, q in ipairs(r411.cfgList(y)) do
		if not p[string.lower(q.name)] then
			pcall(delfile, r411.cfgPath(y, q.name))
		end
	end
end

r411.cfgMigrate = function()
	for y, q in pairs(r411.CFG_KINDS) do
		local p = r403[q.store]

		if type(p) == "string" and p ~= "" then
			local T = {}

			for k, k in ipairs(r411.cfgList(y)) do
				T[string.lower(k.name)] = true
			end

			local k = 0

			for P in string.gmatch(p, "[^\30]+") do
				local p, h = string.match(P, "^([^\29]*)\29(.*)$")
				p = r411.cfgName(p)
				k = if p ~= "" and not T[string.lower(p)] then if pcall(writefile, r411.cfgPath(y, p), h or "") then k + 1 else k else k
			end

			if k > 0 then
				r401:log(("Market: moved %d saved %s config(s) into Auto-Configs"):format(k, y), "INFO")
			end

			r403[q.store] = nil
		end
	end
end

r411.cfgSnap = function(y)
	local q = r411.CFG_KINDS[y]
	if not q then
		return ""
	end
	y = {}

	for p, T in ipairs(q.flags) do
		local q = r403[T]
		y[p] = type(q) == "string" and q or ""
	end

	return table.concat(y, "\31")
end

r411.cfgApply = function(y, q)
	local p = r411.CFG_KINDS[y]
	if not p then
		return
	end
	y = {}

	for T in string.gmatch(tostring(q or "") .. "\31", "([^\31]*)\31") do
		y[#y + 1] = T
	end

	for q, T in ipairs(p.flags) do
		r403[T] = y[q] or ""
	end
end

r411.cfgSel = function(y)
	local q = r411.CFG_KINDS[y]
	y = q and r403[q.sel]
	return type(y) == "string" and y or ""
end

r411.cfgSave = function(y, q)
	local p = r411.CFG_KINDS[y]
	if not p then
		return nil, "bad kind"
	end
	q = r411.cfgName(q)
	if q == "" then
		return nil, "give it a name first"
	end
	local T, k, P = r411.cfgList(y), r411.cfgSnap(y), false

	for h, h in ipairs(T) do
		if string.lower(h.name) == string.lower(q) then
			q = h.name
			h.data = k
			P = true
			break
		end
	end

	if not P then
		if #T >= r411.CFG_MAX then
			return nil, r411.CFG_MAX .. " configs is the limit"
		end
		T[#T + 1] = { name = q, data = k }
	end

	r411.cfgWrite(y, T)
	r403[p.sel] = q
	return q, nil
end

r411.cfgLoad = function(y, q)
	local p = r411.CFG_KINDS[y]
	if not p then
		return false
	end

	for T, T in ipairs(r411.cfgList(y)) do
		if T.name == q then
			r411.cfgApply(y, T.data)
			r403[p.sel] = T.name
			return true
		end
	end

	return false
end

r411.cfgDelete = function(y, q)
	local p = r411.CFG_KINDS[y]
	if not p then
		return false
	end
	local T, k = r411.cfgList(y), false

	for P = #T, 1, -1 do
		if T[P].name == q then
			table.remove(T, P)
			k = true
		end
	end

	if not k then
		return false
	end
	r411.cfgWrite(y, T)

	if r411.cfgSel(y) == q then
		r403[p.sel] = T[1] and T[1].name or ""
	end

	return true
end

r411.cfgCycle = function(y, q)
	local p = r411.CFG_KINDS[y]
	if not p then
		return nil
	end
	local T = r411.cfgList(y)
	if #T == 0 then
		return nil
	end
	local k, P = r411.cfgSel(y), 0

	for h, _ in ipairs(T) do
		if _.name == k then
			P = h
			break
		end
	end

	k = T[if P == 0 then q < 0 and #T or 1 else (P - 1 + q) % #T + 1]
	r411.cfgApply(y, k.data)
	r403[p.sel] = k.name
	return k.name
end

r411.MAP_KEYS = { Metro = "metro", ["City-13"] = "city13", ["Metro Tunnels PVP"] = "tunnels_pvp", ["Metro Tunnels CO-OP"] = "tunnels_pve" }
r411.MAP_ID_KEYS = { Metro = "metro", City13 = "city13", MetroTunnelsPVP = "tunnels_pvp", MetroTunnelsPVE = "tunnels_pve" }
r411.mapCache = { t = 0, name = nil, id = nil, mode = nil, solved = false }

r411.mapInfo = function()
	local y, q = r411.mapCache, os.clock()
	if y.solved and q - y.t < 2 then
		return y
	end
	y.t = q
	y.name = nil
	y.id = nil
	y.mode = nil

	pcall(function()
		local q = workspace:GetAttribute("MapName")

		if type(q) == "string" and q ~= "" then
			y.name = q
		end
	end)

	pcall(function()
		local q = game:GetService("ReplicatedFirst"):FindFirstChild("ServerInfo")
		if not q then
			return
		end
		local p = q:GetAttribute("MapId")

		if type(p) == "string" and p ~= "" then
			y.id = p
		end

		p = q:GetAttribute("GameMode")

		if type(p) == "string" and p ~= "" then
			y.mode = p
		end
	end)

	if not y.name and not y.id then
		pcall(function()
			local q = r2_5:FindFirstChild("ServerStatus")
			local C = q and (q:FindFirstChild("SpawnPOIs"))
			if not C then
				return
			end
			q = C:GetAttributes()

			if q.Airfield or q.Castle or q.Dorms then
				y.name = "City-13"
			end
		end)
	end

	y.solved = y.name ~= nil or y.id ~= nil
	return y
end

r411.mapKey = function()
	local y = r411.mapInfo()
	return y.name and r411.MAP_KEYS[y.name] or y.id and r411.MAP_ID_KEYS[y.id] or nil
end

r411.mapName = function()
	return r411.mapInfo().name
end

r411.mapId = function()
	return r411.mapInfo().id
end

r411.mapLabel = function()
	local y = r411.mapInfo()
	return y.name or y.id or "Unknown"
end

r411.inMetro = function()
	return r411.mapKey() == "metro"
end

r411.VENDOR_MAPS = { metro = true, city13 = true }

r411.atVendorMap = function()
	local y = r411.mapKey()
	return y ~= nil and r411.VENDOR_MAPS[y] == true
end

r411.inRaid = function()
	local y = r411.mapKey()
	return y ~= nil and y ~= "metro"
end

r411.VAULT_DIR = "Fem.Hook/vault"
r411.vaultState = { t = 0, count = 0, value = 0, tier = 0, err = nil, at = nil }

r411.vaultFolder = function()
	local y

	pcall(function()
		local q = r2_5:FindFirstChild("Players")
		local p = q and (q:FindFirstChild(r92.LocalPlayer.Name))
		q = p and (p:FindFirstChild("VaultStorage"))
		y = q and (q:FindFirstChild("Inventory"))
	end)

	return y
end

r411.vaultScan = function()
	local y = r411.vaultFolder()
	if not y then
		return nil, "vault not replicated"
	end
	local q = {}

