r411.vaultText = function(C)
	local y, q = {}, 0

	local function p(T)
		q += 1
		y[q] = T
	end

	p(("Vault dump  -  %s"):format(tostring(C.saved_date)))
	p(("Player     : %s"):format(tostring(C.player)))
	p(("Map        : %s"):format(tostring(C.map)))
	p(("Vault tier : %s"):format(tostring(C.vault_tier)))
	p(("Items      : %d   Value: %d RUB"):format(C.item_count, C.total_value))
	p("----------------------------------------------------------")

	local function q(T, k)
		for P, P in ipairs(T) do
			local T, h = k .. tostring(P.name), P.amount or 1
			T = if P.value then (if h > 1 then T .. " x" .. P.amount else T) .. "   " .. P.value .. " RUB" else if h > 1 then T .. " x" .. P.amount else T
			p(if P.quest_needed then T .. "   [QUEST]" else T)

			if P.contents then
				q(P.contents, k .. "    ")
			end

			if P.attachments then
				q(P.attachments, k .. "  + ")
			end
		end
	end

	q(C.items, "")
	return table.concat(y, "\10")
end

r411.vaultSave = function(y)
	local q = r411.vaultState
	if not (writefile and isfolder and makefolder) then
		q.err = "no file api"
		return false, q.err
	end

	if not r411.inMetro() then
		q.err = "not in Metro (" .. r411.mapLabel() .. ")"
		return false, q.err
	end
	local p, T = r411.vaultScan()
	if not p then
		q.err = T or "scan failed"
		return false, q.err
	end

	if p.item_count == 0 and not y then
		q.err = "vault read empty - kept last dump"
		return false, q.err
	end

	y, T = pcall(function()
		if not isfolder("Fem.Hook") then
			makefolder("Fem.Hook")
		end

		if not isfolder(r411.VAULT_DIR) then
			makefolder(r411.VAULT_DIR)
		end

		local k = r411.VAULT_DIR .. "/" .. p.player
		writefile(k .. ".json", game:GetService("HttpService"):JSONEncode(p))
		writefile(k .. ".txt", r411.vaultText(p))
	end)

	if not y then
		q.err = tostring(T)
		return false, q.err
	end
	q.t, q.at = os.clock(), os.date("%H:%M:%S")
	q.count = p.item_count
	q.value = p.total_value
	q.tier = p.vault_tier
	q.err = nil
	T = r411.vaultCountCache
	T.t = 0
	T.map = nil
	T.disk = nil
	return true, p
end

r411.vaultCached = function()
