		local C = isfile and (isfile(q))

		if C then
			y = game:GetService("HttpService"):JSONDecode(readfile(q))
		end
	end)

	return y
end

r411.vaultCountCache = { t = 0, map = nil, disk = nil, diskT = 0 }

r411.vaultCountLive = function()
