	end
	q.t = p
	local p = {}

	pcall(function()
		local function T(k, P)
			if not k or P > 6 then
				return
			end

			for h, h in ipairs(k:GetChildren()) do
				local k, _ = string.lower(r411.itemBase(h.Name)), h:GetAttribute("Amount")
				p[k] = (p[k] or 0) + (type(_) == "number" and _ > 1 and (math.floor(_)) or 1)
				T(h:FindFirstChild("Inventory"), P + 1)
				T(h:FindFirstChild("Attachments"), P + 1)
			end
		end

		T(y, 0)
	end)

	q.map = p
