r411.vaultCountDisk = function()
	local y = r411.vaultCountCache

	if y.disk then
		if next(y.disk) ~= nil then
			return y.disk
		end

		if os.clock() - y.diskT < 30 then
			return y.disk
		end
	end

	y.diskT = os.clock()
	local q, p = {}, r411.vaultCached()

	if p and type(p.items) == "table" then
		local function C(T)
			for k, P in ipairs(T) do
				k = string.lower(tostring(P.base or P.name or ""))

				if k ~= "" then
					q[k] = (q[k] or 0) + (P.amount or 1)
				end

				if P.contents then
					C(P.contents)
				end

				if P.attachments then
					C(P.attachments)
				end
			end
		end

		pcall(C, p.items)
	end

	y.disk = q
	return q
end

r411.vaultCounts = function()
	local y = r411.vaultCountLive()
	if y and (r411.inMetro() or next(y) ~= nil) then
		return y, "live"
	end
	local q = r411.vaultCountDisk()
	if next(q) ~= nil then
		return q, "disk"
	end

	if y then
		return y, "live"
	end
	return q, "disk"
end

r411.vaultHas = function(y)
