end

r411.qimCache = { t = 0, map = nil }

r411.questItemMap = function()
	local y, q = r411.qimCache, os.clock()
	if y.map and q - y.t < 3 then
		return y.map
	end
	y.t = q
	local q = {}

	pcall(function()
		local p = r408("questwish_hide_done", true)

		for T, k in ipairs(r411.questIndex()) do
			if not k.done then
				T = k.active and "active" or "future"

				for P, h in ipairs(k.needs) do
					if not (p and h.done) then
						P = r411.itemBase(h.name)
						local C = string.lower(P)
						local p = q[C]

						if not p then
							p = {
								name = P,
								active = {},
								future = {},
								kind = h.kind,
							}

							q[C] = p
						end

						C = p[T]

						C[#C + 1] = {
							quest = k.label,
							id = k.id,
							amount = h.amount,
							done = h.done,
							away = k.away,
						}

						if T == "active" then
							p.amount = (p.amount or 0) + (h.amount or 1)
							p.kind = p.kind or h.kind
						end
					end
				end
			end
		end
	end)

	local C, p = 0, 0

	for T, k in pairs(q) do
		C, p = C + 1, p + #T * 7 + #k.active * 131 + #k.future * 17
	end

	y.sig = C .. ":" .. p
	y.map = q
	return q
end

r411.questItemRows = function(y, q)
	local p = r411.questItemMap()[string.lower(r411.itemBase(tostring(y)))]
	if not p then
		return nil
	end
	local C, y = {}, 0

	for T, T in ipairs(p.active) do
		y += 1

		C[y] = {
			quest = T.quest,
			active = true,
			away = 0,
		}
	end

	for T, T in ipairs(p.future) do
		y += 1

		C[y] = {
			quest = T.quest,
			active = false,
			away = T.away or 0,
		}
	end

	if y == 0 then
		return nil
	end
	q = q or 4

	if y > q then
		for T = y, q + 1, -1 do
			C[T] = nil
		end

		C[q + 1] = {
			more = y - q,
		}
	end

	return C, p, #p.active > 0
end

