		r411.envHeld = {}

		r411.nearly = function(t15, t16)
			return t15 > t16 - 0.001 and t15 < t16 + 0.001
		end

		r411.same = function(t9, t10)
			local t3 = typeof(t9)
			if t3 ~= typeof(t10) then
				return false
			end

			if t3 == "number" then
				return r411.nearly(t9, t10)
			end

			if t3 == "Color3" then
				return r411.nearly(t9.R, t10.R) and r411.nearly(t9.G, t10.G) and r411.nearly(t9.B, t10.B)
			end

			if t3 == "Vector3" then
				return r411.nearly(t9.X, t10.X) and r411.nearly(t9.Y, t10.Y) and r411.nearly(t9.Z, t10.Z)
			end
			return t9 == t10
		end

		r411.envHold = function(t15, t16, t17, t18, t19)
